"use client";

import { SimpleGrid, Stack, Text } from '@mantine/core';

import { GridItem } from '@/components/rendyn-libraries/mantine/upstream/src/demos/core/SimpleGrid/_demo-item';

const items = Array(3)
  .fill(0)
  .map((_, index) => <GridItem key={index}>{index + 1}</GridItem>);

function Demo() {
  return (
    <Stack>
      <div>
        <Text mb="xs" fw={500}>
          auto-fill
        </Text>
        <SimpleGrid minColWidth="200px" autoFlow="auto-fill">
          {items}
        </SimpleGrid>
      </div>
      <div>
        <Text mb="xs" fw={500}>
          auto-fit
        </Text>
        <SimpleGrid minColWidth="200px" autoFlow="auto-fit">
          {items}
        </SimpleGrid>
      </div>
    </Stack>
  );
}
const RendynExampleComponent = Demo;
export function RendynExample() { return <RendynExampleComponent  />; }

"use client";

import cx from 'clsx';
import { Box, BoxProps, ElementProps, Text } from '@mantine/core';
import classes from '@/components/rendyn-libraries/mantine/upstream/src/demos/core/SimpleGrid/_item.module.css';

interface GridItemProps extends BoxProps, ElementProps<'div'> {}

export function GridItem({ className, children, ...others }: GridItemProps) {
  return (
    <Box className={cx(classes.item, className)} {...others}>
      <Text className={classes.label}>{children}</Text>
    </Box>
  );
}

export const defaultItems = Array(5)
  .fill(0)
  .map((_, index) => <GridItem key={index}>{index + 1}</GridItem>);

.item {
  background-color: light-dark(var(--mantine-color-blue-0), var(--mantine-color-dark-4));
  padding: var(--mantine-spacing-md);
}

.label {
  color: light-dark(var(--mantine-color-blue-6), var(--mantine-color-dimmed));
  font-size: var(--mantine-font-size-xl);
  font-weight: bold;
  text-align: center;
}

